import sys
import math

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    n = int(data[0]); m = int(data[1]); k = int(data[2])
    a = [int(x) for x in data[3:3+k]]

    for i in range(k - 1):
        if math.gcd(a[i], a[i+1]) != 1:
            print("NO")
            return

    L = 1
    for x in a:
        L = L // math.gcd(L, x) * x
        if L > n:
            print("NO")
            return

    j = 0
    mod = 1
    broke = False
    break_t = 0
    for t in range(1, k + 1):
        at = a[t-1]
        r = (1 - t) % at
        g = math.gcd(mod, at)
        if (r - j) % g != 0:
            print("NO")
            return
        mod_g = mod // g
        a_g = at // g
        rhs = (r - j) // g
        if a_g == 1:
            x = 0
        else:
            inv = pow(mod_g % a_g, -1, a_g)
            x = (rhs * inv) % a_g
        j = j + mod * x
        mod = mod * a_g
        j %= mod
        if mod > m:
            broke = True
            break_t = t
            break

    if broke:
        if j == 0:
            print("NO")
            return
        for t in range(break_t + 1, k + 1):
            if (j - (1 - t)) % a[t-1] != 0:
                print("NO")
                return
        if j > m - k + 1:
            print("NO")
            return
    else:
        if j == 0:
            j = mod
        if j > m - k + 1:
            print("NO")
            return

    for t in range(1, k + 1):
        b = (j + t - 1) // a[t-1]
        if math.gcd(L // a[t-1], b) != 1:
            print("NO")
            return

    print("YES")

if __name__ == "__main__":
    solve()
